fn int_to_str(n: Int) -> Str {
    let digits = vec("0123456789")
    let mut result = Str
    let mut n_copy = n
    while n_copy > 0 {
        let digit = n_copy % 10
        n_copy = n_copy / 10
        let char = digits.get(digit)
        result = concat(vec(char), result)
    }
    result
}

